# ============================================================
# HASHING
# ============================================================

def sha256(data):
    return hashlib.sha256(
        str(data).encode("utf-8")
    ).hexdigest()


# ============================================================
# FRAUD DETECTION
# ============================================================

def fraud_score(amount, recipient):
    score = 0
    reasons = []

    if amount > 10000:
        score += 35
        reasons.append("High transaction amount")

    if amount > 20000:
        score += 30
        reasons.append("Very high transaction amount")

    if recipient.lower() in ["unknown", "scammer"]:
        score += 60
        reasons.append("High-risk recipient")

    return score, reasons


# ============================================================
# TRANSACTION
# ============================================================

def make_transaction(recipient, amount):

    score, reasons = fraud_score(amount, recipient)

    if score >= 70:
        return False, score, reasons

    if amount > st.session_state.balance:
        return False, 0, ["Insufficient balance"]

    tx_id = str(uuid.uuid4())[:12]

    transaction = {
        "id": tx_id,
        "time": datetime.now().strftime("%d %b %Y | %I:%M %p"),
        "recipient": recipient,
        "amount": amount,
        "status": "SUCCESS",
        "hash": ""
    }

    transaction_hash = sha256(transaction)

    transaction["hash"] = transaction_hash

    previous_hash = (
        st.session_state.blockchain[-1]["hash"]
        if st.session_state.blockchain
        else "GENESIS"
    )

    block = {
        "index": len(st.session_state.blockchain) + 1,
        "timestamp": transaction["time"],
        "transaction_id": tx_id,
        "previous_hash": previous_hash,
        "hash": sha256(
            str(transaction_hash) + previous_hash
        )
    }

    st.session_state.balance -= amount
    st.session_state.transactions.insert(0, transaction)
    st.session_state.blockchain.insert(0, block)

    return True, score, []


