def send_money():

    st.markdown(
        """
        <div class="page-title">Send Money</div>
        <div class="page-subtitle">
            Fast, secure and protected payments
        </div>
        """,
        unsafe_allow_html=True
    )

    st.write("")

    left, right = st.columns([1.1, .9])

    with left:

        st.markdown(
            '<div class="card">',
            unsafe_allow_html=True
        )

        recipient = st.text_input(
            "Recipient MoneyPenny ID",
            placeholder="example@money"
        )

        amount = st.number_input(
            "Amount",
            min_value=1.0,
            max_value=100000.0,
            value=100.0,
            step=100.0
        )

        pin = st.text_input(
            "UPI PIN",
            type="password",
            max_chars=4
        )

        if st.button("➤   Send Secure Payment"):

            if not recipient:
                st.error("Please enter recipient.")

            elif pin != "1234":
                st.error("Incorrect UPI PIN.")

            else:

                st.markdown(
                    """
                    <div class="processing">
                    🔄 Processing secure transaction...
                    </div>
                    """,
                    unsafe_allow_html=True
                )

                time.sleep(1)

                success, score, reasons = make_transaction(
                    recipient,
                    amount
                )

                if success:

                    st.markdown(
                        f"""
                        <div class="success">
                        ✓ Payment Successful<br><br>
                        ₹{amount:,.2f} sent to
                        <b>{recipient}</b>
                        </div>
                        """,
                        unsafe_allow_html=True
                    )

                    time.sleep(.5)
                    st.rerun()

                else:

                    st.markdown(
                        f"""
                        <div class="failure">
                        ✕ Transaction Blocked<br><br>
                        Security score: {score}<br>
                        {"<br>".join(reasons)}
                        </div>
                        """,
                        unsafe_allow_html=True
                    )

        st.markdown("</div>", unsafe_allow_html=True)

    with right:

        st.markdown(
            """
            <div class="card">

            <h3>Security Protection</h3>

            <p>🔐 SHA-256 transaction hashing</p>
            <p>🛡️ Fraud detection</p>
            <p>⬡ Blockchain verification</p>
            <p>🔑 UPI PIN authentication</p>

            </div>
            """,
            unsafe_allow_html=True
        )


