def qr_payment():

    st.markdown(
        """
        <div class="page-title">QR Payment</div>

        <div class="page-subtitle">
            Generate your MoneyPenny payment QR
        </div>
        """,
        unsafe_allow_html=True
    )

    st.write("")

    try:
        import qrcode

        qr = qrcode.make(
            f"moneypenny://pay?id={st.session_state.money_id}"
        )

        qr_path = "moneypenny_qr.png"
        qr.save(qr_path)

        left, right = st.columns(2)

        with left:

            st.markdown(
                '<div class="card">',
                unsafe_allow_html=True
            )

            st.image(
                qr_path,
                width=280
            )

            st.success("QR generated successfully.")

            st.download_button(
                "Download QR",
                open(qr_path, "rb").read(),
                "moneypenny_qr.png",
                "image/png"
            )

            st.markdown("</div>", unsafe_allow_html=True)

        with right:

            st.markdown(
                f"""
                <div class="card">

                <h3>Payment ID</h3>

                <div style="
                    font-size:24px;
                    font-weight:800;
                    color:#00c5ff;
                ">
                {st.session_state.money_id}
                </div>

                <p style="color:#91b7ef;">
                Share this QR to receive payments.
                </p>

                </div>
                """,
                unsafe_allow_html=True
            )

    except ImportError:

        st.error(
            "Install QR support with: pip install qrcode[pil]"
        )


