# ACCOUNT MANAGEMENT
# ============================================================

def account_management():

    st.markdown(
        """
        <div class="page-title">Account Management</div>

        <div class="page-subtitle">
            Manage your MoneyPenny account
        </div>
        """,
        unsafe_allow_html=True
    )

    st.write("")

    st.markdown(
        '<div class="card">',
        unsafe_allow_html=True
    )

    name = st.text_input(
        "Full Name",
        value=st.session_state.user_name
    )

    money_id = st.text_input(
        "MoneyPenny ID",
        value=st.session_state.money_id
    )

    phone = st.text_input(
        "Phone Number",
        value=st.session_state.phone
    )

    email = st.text_input(
        "Email",
        value=st.session_state.email
    )

    new_password = st.text_input(
        "Password",
        value=st.session_state.password,
        type="password"
    )

    if st.button("✓   Save Account Changes"):

        st.session_state.user_name = name
        st.session_state.money_id = money_id
        st.session_state.phone = phone
        st.session_state.email = email
        st.session_state.password = new_password

        st.success("Account details updated successfully.")

    st.markdown("</div>", unsafe_allow_html=True)

    st.write("")

    st.markdown(
        """
        <div class="card">

        <h3>Account Security</h3>

        <p>🟢 Account Protection — ACTIVE</p>
        <p>🟢 Transaction Encryption — ACTIVE</p>
        <p>🟢 Fraud Monitoring — ACTIVE</p>
        <p>🟢 Blockchain Ledger — ACTIVE</p>

        </div>
        """,
        unsafe_allow_html=True
    )


